"use strict";

// JS facade over the C bridge namespace injected by the loader as
// module.native (see docs/node-compatibility.md §3.4.3).

const native = module.native;

module.exports = {
    crc32: (buffer) => native.crc32(buffer),
    abiProbe: () => native.abiProbe(),
    hasNative: native !== undefined,
};
